const guards=[{"tgname":"guard_immutable_ebay_offer_identity","proname":"guard_immutable_ebay_offer_identity","source_md5":"3d0b5fee29130c9f067870b7606d1c8f","definition":"CREATE OR REPLACE FUNCTION sellerpilot_private.guard_immutable_ebay_offer_identity()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_marker text := nullif(current_setting(\n    'sellerpilot.provider_listing_lineage_rebind', true\n  ), '');\n  v_resources jsonb;\nbegin\n  if old.provider_resource_id is not null\n     and (\n       new.provider_resource_id is distinct from old.provider_resource_id\n       or new.remote_id is distinct from old.remote_id\n       or new.market is distinct from old.market\n       or new.target_id is distinct from old.target_id\n       or new.marketplace_sku is distinct from old.marketplace_sku\n     ) then\n    raise exception 'immutable ebay listing identity cannot change';\n  end if;\n\n  if old.provider_resource_id is null\n     and new.provider_resource_id is not null then\n    if old.channel_key <> 'ebay'\n       or not exists (\n         select 1\n           from sellerpilot_private.provider_listing_lineage_attestations attestation\n           join sellerpilot_private.channel_gateway_jobs job\n             on job.id = attestation.gateway_job_id\n          where attestation.listing_id = old.id\n            and attestation.gateway_job_id::text = v_marker\n            and attestation.expected_remote_id = trim(new.remote_id)\n            and attestation.verified_remote_id = trim(new.remote_id)\n            and attestation.market = new.market\n            and attestation.target_id = new.target_id\n            and attestation.marketplace_sku = trim(new.marketplace_sku)\n            and attestation.provider_resource_id = trim(new.provider_resource_id)\n            and job.listing_id = old.id\n            and job.channel = 'ebay'\n            and job.operation = 'listing.lineage.verify'\n            and job.status = 'running'\n            and job.claim_token is not null\n            and job.lease_expires_at > clock_timestamp()\n       ) then\n      raise exception 'verified ebay offer identity binding required';\n    end if;\n  end if;\n\n  if new.channel_key = 'ebay'\n     and new.provider_resource_id is not null\n     and (\n       old.provider_resource_id is null\n       or new.remote_resources is distinct from old.remote_resources\n     )\n     and new.remote_resources <> '{}'::jsonb then\n    v_resources := new.remote_resources->'resources';\n    if jsonb_typeof(v_resources) <> 'object'\n       or v_resources->>'offerId' is distinct from new.provider_resource_id\n       or v_resources->>'listingId' is distinct from new.remote_id\n       or v_resources->>'sku' is distinct from new.marketplace_sku\n       or upper(coalesce(v_resources->>'marketplaceId', ''))\n            is distinct from upper(coalesce(new.target_id, '')) then\n      raise exception 'verified ebay remote resources must preserve immutable identity';\n    end if;\n  end if;\n  return new;\nexception when invalid_text_representation then\n  raise exception 'verified ebay offer identity binding required';\nend;\n$function$\n"},{"tgname":"guard_product_listing_seller_lineage","proname":"guard_product_listing_seller_lineage","source_md5":"38e1a8cf1ece02889810c2a6da2696d0","definition":"CREATE OR REPLACE FUNCTION sellerpilot_private.guard_product_listing_seller_lineage()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_attempt record;\n  v_credential_key text;\n  v_job record;\n  v_sensitive_completion boolean := false;\n  v_binding_verified boolean := false;\n  v_backfill_key text;\n\nbegin\n  if nullif(current_setting('sellerpilot.coupang_exact_post_price_reconcile', true), '') is not null then\n    if sellerpilot_private.coupang_exact_post_price_listing_update_allowed(\n      to_jsonb(old), to_jsonb(new),\n      current_setting('sellerpilot.coupang_exact_post_price_reconcile', true)\n    ) is not true then\n      raise exception 'invalid exact Coupang post-price listing projection'\n        using errcode = '55000';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.coupang_exact_live_price_drift_adjudicate', true), '') is not null then\n    if sellerpilot_private.coupang_exact_live_price_drift_listing_update_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.coupang_exact_live_price_drift_adjudicate', true)\n    ) is not true then\n      raise exception 'invalid exact Coupang price-drift listing projection'\n        using errcode = '55000';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.coupang_exact_live_reconcile',true),'') is not null then\n    if sellerpilot_private.coupang_exact_live_listing_update_allowed(to_jsonb(old),to_jsonb(new),current_setting('sellerpilot.coupang_exact_live_reconcile',true)) is not true then raise exception 'invalid exact Coupang listing projection'; end if;\n    return new;\n  end if;\n\n  if current_setting('sellerpilot.smartstore_manual_adoption_attestation', true) <> '' then\n    if not sellerpilot_private.smartstore_manual_adoption_listing_transition_allowed(\n      to_jsonb(old), to_jsonb(new)\n    ) then\n      raise exception 'SMARTSTORE_MANUAL_ADOPTION_LISTING_TRANSITION_INVALID';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.elevenst_cookie_create_get_bind', true), '') is not null then\n    if not sellerpilot_private.elevenst_cookie_create_listing_update_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.elevenst_cookie_create_get_bind', true)::uuid\n    ) then\n      raise exception 'invalid exact 11st cookie create GET bind';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.coupang_exact_rep_apply', true), '') is not null then\n    if not sellerpilot_private.coupang_exact_rep_listing_update_allowed(\n      to_jsonb(old),to_jsonb(new),\n      current_setting('sellerpilot.coupang_exact_rep_apply', true)\n    ) then\n      raise exception 'invalid Coupang exact representative listing projection';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_adopted_image_binding_restore', true), '') is not null then\n    if not sellerpilot_private.qoo10_adopted_image_binding_restore_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.qoo10_adopted_image_binding_restore', true)\n    ) then\n      raise exception 'invalid exact Qoo10 adopted image binding restore';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_adopted_content_validation_restore', true), '') is not null then\n    if not sellerpilot_private.qoo10_adopted_content_validation_restore_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.qoo10_adopted_content_validation_restore', true)\n    ) then\n      raise exception 'invalid exact Qoo10 adopted content validation restore';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_already_live_adoption', true), '') is not null then\n    if not sellerpilot_private.qoo10_exact_already_live_listing_update_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.qoo10_already_live_adoption', true)::uuid\n    ) then\n      raise exception 'invalid exact Qoo10 already-live adoption';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.shopee_existing_adoption', true), '') is not null then\n    if not sellerpilot_private.shopee_existing_adoption_projection_allowed(\n      to_jsonb(old), to_jsonb(new),\n      current_setting('sellerpilot.shopee_existing_adoption', true)::uuid\n    ) then\n      raise exception 'invalid Shopee existing adoption projection';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.elevenst_manual_live_reconciliation', true), '') is not null then\n    if not sellerpilot_private.elevenst_manual_live_reconciliation_update_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.elevenst_manual_live_reconciliation', true)::uuid\n    ) then\n      raise exception 'invalid exact 11st manual live reconciliation';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_partial_manual_apply', true), '') is not null then\n    if not sellerpilot_private.qoo10_partial_manual_listing_update_allowed(\n      to_jsonb(old),to_jsonb(new),\n      current_setting('sellerpilot.qoo10_partial_manual_apply', true)\n    ) then\n      raise exception 'invalid exact Qoo10 partial/manual listing projection';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.lazada_exact_update_apply', true), '') is not null then\n    if not sellerpilot_private.lazada_exact_listing_projection_allowed(\n      to_jsonb(old),to_jsonb(new),\n      current_setting('sellerpilot.lazada_exact_update_apply', true)\n    ) then\n      raise exception 'invalid Lazada exact listing projection';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.temu_publication_apply', true), '') is not null then\n    if not sellerpilot_private.temu_server_owned_listing_update_allowed(\n      to_jsonb(old),to_jsonb(new),\n      current_setting('sellerpilot.temu_publication_apply', true)\n    ) then\n      raise exception 'invalid Temu server-owned listing projection';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_shipping_s1_activation_apply', true), '') is not null then\n    if not sellerpilot_private.qoo10_shipping_s1_activation_listing_update_allowed(\n      to_jsonb(old), to_jsonb(new),\n      current_setting('sellerpilot.qoo10_shipping_s1_activation_apply', true)\n    ) then\n      raise exception 'invalid exact Qoo10 shipping S1 activation listing update';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_s1_activation_apply', true), '') is not null then\n    if not sellerpilot_private.qoo10_exact_s1_activation_listing_update_allowed(\n      to_jsonb(old),to_jsonb(new),\n      current_setting('sellerpilot.qoo10_s1_activation_apply', true)\n    ) then\n      raise exception 'invalid exact Qoo10 S1 activation listing update';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_exact_adultyn_rejection_job', true), '') is not null then\n    if not sellerpilot_private.qoo10_exact_adultyn_rejection_restore_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.qoo10_exact_adultyn_rejection_job', true)\n    ) then\n      raise exception 'invalid exact Qoo10 AdultYN rejection restore';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_exact_preprovider_gate_job', true), '') is not null then\n    if not sellerpilot_private.qoo10_exact_preprovider_gate_restore_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.qoo10_exact_preprovider_gate_job', true)\n    ) then\n      raise exception 'invalid exact Qoo10 pre-provider gate restore';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_exact_origin_rejection_job', true), '') is not null then\n    if not sellerpilot_private.qoo10_exact_origin_rejection_restore_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.qoo10_exact_origin_rejection_job', true)\n    ) then\n      raise exception 'invalid exact Qoo10 origin-type rejection restore';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_rollback_retry_job', true), '') is not null then\n    if not sellerpilot_private.qoo10_rollback_update_retry_restore_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.qoo10_rollback_retry_job', true)\n    ) then\n      raise exception 'invalid Qoo10 rollback update retry restore';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.qoo10_create_rollback_source_job', true), '') is not null then\n    if not sellerpilot_private.qoo10_listing_create_rollback_update_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.qoo10_create_rollback_source_job', true)\n    ) then\n      raise exception 'invalid Qoo10 listing create rollback recovery';\n    end if;\n    return new;\n  end if;\n  if nullif(current_setting('sellerpilot.publication_source_pending_job', true), '') is not null then\n    if not sellerpilot_private.listing_publication_source_pending_update_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.publication_source_pending_job', true)\n    ) then\n      raise exception 'invalid source publication pending update';\n    end if;\n    return new;\n  end if;\n\n  if nullif(current_setting('sellerpilot.publication_review_apply', true), '') is not null then\n    if not sellerpilot_private.listing_publication_review_update_allowed(\n      to_jsonb(old),\n      to_jsonb(new),\n      current_setting('sellerpilot.publication_review_apply', true)\n    ) then\n      raise exception 'invalid listing publication review update';\n    end if;\n    return new;\n  end if;\n\n  if current_setting('sellerpilot.remote_publication_backfill', true) = 'legacy-unverified-v1' then\n    if not sellerpilot_private.legacy_remote_publication_downgrade_allowed(\n      to_jsonb(old),\n      to_jsonb(new)\n    ) then\n      raise exception 'invalid legacy remote publication downgrade';\n    end if;\n    return new;\n  end if;\n\n  if old.seller_account_key is null\n     and new.seller_account_key is not null\n     and new.seller_account_key is distinct from old.seller_account_key\n     and current_setting('sellerpilot.static_listing_lineage_backfill', true) = 'verified-v1' then\n    if (to_jsonb(new) - 'seller_account_key')\n       is distinct from (to_jsonb(old) - 'seller_account_key') then\n      raise exception 'static listing lineage backfill may only bind seller account key';\n    end if;\n\n    select sellerpilot_private.verified_static_listing_lineage_key(old.id)\n      into v_backfill_key;\n    if v_backfill_key is null\n       or new.seller_account_key is distinct from v_backfill_key then\n      raise exception 'verified static listing lineage evidence required';\n    end if;\n    return new;\n  end if;\n\n  if old.marketplace_sku is not null\n     and new.marketplace_sku is distinct from old.marketplace_sku then\n    raise exception 'product listing marketplace sku is immutable';\n  end if;\n  if old.operation_attempt_id is not null and new.operation_attempt_id is null then\n    raise exception 'product listing operation lineage cannot be cleared';\n  end if;\n  if new.seller_account_key is not null\n     and old.seller_account_key is not null\n     and new.seller_account_key is distinct from old.seller_account_key then\n    raise exception 'product listing seller lineage is immutable';\n  end if;\n\n  if new.operation_attempt_id is not null then\n    select a.id, a.credential_id, a.channel, a.operation, a.status, a.seller_account_key\n      into v_attempt\n      from sellerpilot_private.channel_operation_attempts a\n     where a.id = new.operation_attempt_id;\n    if found then\n      select c.seller_account_key into v_credential_key\n        from sellerpilot_private.channel_credentials c\n       where c.id = v_attempt.credential_id\n         and c.channel = v_attempt.channel;\n      if v_attempt.channel <> new.channel_key then\n        raise exception 'product listing attempt channel mismatch';\n      end if;\n      if v_attempt.operation in ('listing.update', 'listing.stop', 'price.update', 'inventory.update') and (\n        old.seller_account_key is null\n        or v_attempt.seller_account_key is null\n        or v_credential_key is null\n        or old.seller_account_key is distinct from v_attempt.seller_account_key\n        or old.seller_account_key is distinct from v_credential_key\n      ) then\n        raise exception 'product listing seller account mismatch';\n      end if;\n      if v_attempt.operation = 'listing.create'\n         and old.seller_account_key is not null\n         and (\n           v_attempt.seller_account_key is null\n           or old.seller_account_key is distinct from v_attempt.seller_account_key\n           or old.seller_account_key is distinct from v_credential_key\n         ) then\n        raise exception 'product listing seller account mismatch';\n      end if;\n    end if;\n  end if;\n\n  v_sensitive_completion := new.operation_attempt_id is not null\n    and (\n      new.remote_id is distinct from old.remote_id\n      or (new.status is distinct from old.status and new.status in ('published', 'paused', 'failed'))\n      or new.seller_account_key is distinct from old.seller_account_key\n    );\n\n  if old.seller_account_key is not null\n     and (\n       new.remote_id is distinct from old.remote_id\n       or (new.status is distinct from old.status and new.status in ('published', 'paused', 'failed'))\n     )\n     and (new.operation_attempt_id is null or not found) then\n    raise exception 'exact listing operation lineage required';\n  end if;\n\n  if v_sensitive_completion and found and v_attempt.operation in ('listing.create', 'listing.update', 'listing.stop') then\n    select j.id, j.credential_id, j.attempt_id, j.listing_id, j.channel,\n           j.operation, j.status, j.request_payload, j.response_payload,\n           j.seller_account_key\n      into v_job\n      from sellerpilot_private.channel_gateway_jobs j\n     where j.listing_id = new.id\n       and j.attempt_id = new.operation_attempt_id\n       and j.channel = new.channel_key\n       and j.operation = v_attempt.operation\n       and j.status in ('succeeded', 'failed', 'reconciliation_required')\n     order by j.completed_at desc nulls last, j.created_at desc, j.id desc\n     limit 1;\n\n    if not found then\n      -- A local pre-provider validation failure may safely mark the listing as\n      -- failed, but it may not attach or replace a remote identity.\n      if new.status = 'failed'\n         and new.remote_id is not distinct from old.remote_id\n         and new.seller_account_key is not distinct from old.seller_account_key then\n        return new;\n      end if;\n      raise exception 'exact terminal listing gateway job required';\n    end if;\n\n    if v_job.credential_id <> v_attempt.credential_id\n       or v_job.seller_account_key is null\n       or v_attempt.seller_account_key is null\n       or v_credential_key is null\n       or v_job.seller_account_key is distinct from v_attempt.seller_account_key\n       or v_job.seller_account_key is distinct from v_credential_key then\n      raise exception 'terminal listing seller account mismatch';\n    end if;\n\n    if new.status in ('published', 'paused') and (\n      v_job.status <> 'succeeded'\n      or not coalesce((v_job.response_payload->>'ok')::boolean, false)\n      or (new.status = 'paused' and v_attempt.operation <> 'listing.stop' and not (v_attempt.operation in ('listing.create', 'listing.update') and v_job.response_payload#>>'{remoteState,verified}' = 'true' and v_job.response_payload#>>'{remoteState,visibility}' in ('non_public', 'pending_review', 'withdrawn')))\n      or (new.status = 'published' and v_attempt.operation not in ('listing.create', 'listing.update'))\n    ) then\n      raise exception 'successful terminal listing job required';\n    end if;\n\n    if v_attempt.operation in ('listing.update', 'listing.stop') and (\n      old.seller_account_key is null\n      or old.seller_account_key is distinct from v_job.seller_account_key\n    ) then\n      raise exception 'terminal listing seller account mismatch';\n    end if;\n\n    if v_attempt.operation = 'listing.create'\n       and v_job.status = 'succeeded'\n       and coalesce((v_job.response_payload->>'ok')::boolean, false) then\n      if not sellerpilot_private.gateway_listing_create_readback_verified(\n        new.channel_key,\n        v_job.response_payload\n      ) then\n        raise exception 'listing create readback required for seller lineage';\n      end if;\n      if old.seller_account_key is null then\n        new.seller_account_key := v_job.seller_account_key;\n        v_binding_verified := true;\n      elsif old.seller_account_key is distinct from v_job.seller_account_key then\n        raise exception 'terminal listing seller account mismatch';\n      end if;\n      if new.channel_key = 'ebay' and old.marketplace_sku is null then\n        new.marketplace_sku := nullif(trim(v_job.request_payload#>>'{arguments,sku}'), '');\n        if new.marketplace_sku is null then\n          raise exception 'verified ebay marketplace sku required';\n        end if;\n      end if;\n    end if;\n  end if;\n\n  if new.seller_account_key is distinct from old.seller_account_key\n     and old.seller_account_key is not null then\n    raise exception 'product listing seller lineage is immutable';\n  end if;\n  if new.seller_account_key is distinct from old.seller_account_key\n     and new.seller_account_key is null then\n    raise exception 'product listing seller lineage cannot be cleared';\n  end if;\n  if new.seller_account_key is distinct from old.seller_account_key\n     and old.seller_account_key is null\n     and not v_binding_verified then\n    raise exception 'verified listing create completion required for seller lineage';\n  end if;\n  return new;\nend;\n$function$\n"},{"tgname":"guard_verified_ebay_listing_sku_recovery","proname":"guard_verified_ebay_listing_sku_recovery","source_md5":"b1b18c0e2699cb783f4c5e7d278efa25","definition":"CREATE OR REPLACE FUNCTION sellerpilot_private.guard_verified_ebay_listing_sku_recovery()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_marker text := current_setting(\n    'sellerpilot.provider_listing_lineage_rebind', true\n  );\nbegin\n  if old.channel_key <> 'ebay'\n     or old.marketplace_sku is not null\n     or new.marketplace_sku is null\n     or new.marketplace_sku is not distinct from old.marketplace_sku then\n    return new;\n  end if;\n  if not exists (\n    select 1\n      from sellerpilot_private.channel_gateway_jobs job\n     where job.id::text = v_marker\n       and job.id = (\n         nullif(current_setting('sellerpilot.provider_listing_lineage_rebind', true), '')\n       )::uuid\n       and job.listing_id = old.id\n       and job.channel = 'ebay'\n       and job.operation = 'listing.lineage.verify'\n       and job.status = 'running'\n       and job.claim_token is not null\n       and job.lease_expires_at > clock_timestamp()\n       and (\n         nullif(trim(job.request_payload#>>'{arguments,marketplaceSku}'), '')\n           = trim(new.marketplace_sku)\n         or (\n           job.request_payload#>>'{arguments,discoveryMode}'\n             = 'ebay_listing_id_v1'\n           and exists (\n             select 1\n               from sellerpilot_private.provider_listing_lineage_attestations attestation\n              where attestation.gateway_job_id = job.id\n                and attestation.listing_id = old.id\n                and attestation.marketplace_sku = trim(new.marketplace_sku)\n           )\n         )\n       )\n  ) then\n    raise exception 'verified ebay marketplace sku recovery required';\n  end if;\n  return new;\nexception when invalid_text_representation then\n  raise exception 'verified ebay marketplace sku recovery required';\nend;\n$function$\n"}];

