async function rows(db){const result={};for(const [k,t]of Object.entries(tables))result[k]=(await db.query(`select to_jsonb(r) row,md5(to_jsonb(r)::text) hash from sellerpilot_private.${t} r where id=$1`,[ids[k]])).rows[0];return result;}
function fixtureMigration(snapshot){let sql=migration;for(const k of Object.keys(tables))sql=sql.replace(liveHashes[k],snapshot[k].hash);return sql;}
test('exact never-sent expiry preserves original evidence and shared-admin identity, permits normal retry state',async()=>{
 const db=await setup();try{const before=await rows(db);await db.exec(fixtureMigration(before));const after=await rows(db);
 const receipt=(await db.query('select * from sellerpilot_private.smartstore_unclaimed_source_expiry_receipts')).rows[0];
 for(const[k,col]of Object.entries({j:'job_before',a:'attempt_before',l:'listing_before',s:'source_before'}))assert.deepEqual(receipt[col],before[k].row);
 const without=(row,keys)=>Object.fromEntries(Object.entries(row).filter(([k])=>!keys.includes(k)));
 assert.deepEqual(without(after.j.row,['status','error_message','completed_at','updated_at']),without(before.j.row,['status','error_message','completed_at','updated_at']));
 assert.deepEqual(without(after.a.row,['status','http_status','safe_message','completed_at']),without(before.a.row,['status','http_status','safe_message','completed_at']));
 assert.deepEqual(without(after.l.row,['status','failure_class','last_error','updated_at']),without(before.l.row,['status','failure_class','last_error','updated_at']));
 assert.equal(after.j.row.status,'cancelled');assert.equal(after.j.row.attempt_count,0);assert.equal(after.a.row.status,'failed');assert.equal(after.l.row.status,'failed');assert.equal(after.l.row.failure_class,'retryable');assert.equal(after.l.row.remote_id,null);assert.deepEqual(after.s,before.s);
 assert.equal((await db.query('select count(*)::int n from sellerpilot_private.operation_audit')).rows[0].n,1);
 for(const role of ['anon','authenticated','service_role'])assert.equal((await db.query(`select has_table_privilege($1,'sellerpilot_private.smartstore_unclaimed_source_expiry_receipts','SELECT') allowed`,[role])).rows[0].allowed,false);
 }finally{await db.close();}
});
test('claim/provider/receipt/source changes reject even with matching current-row hashes',async()=>{
 const db=await setup();try{for(const patch of [
 `update sellerpilot_private.channel_gateway_jobs set attempt_count=1`,
 `update sellerpilot_private.channel_gateway_jobs set claim_token=gen_random_uuid()`,
 `update sellerpilot_private.channel_gateway_jobs set worker_token_id=gen_random_uuid()`,
 `update sellerpilot_private.channel_gateway_jobs set provider_mutation_started_at=now()`,
 `update sellerpilot_private.channel_gateway_jobs set response_payload='{}'`,
 `update sellerpilot_private.channel_gateway_jobs set credential_refresh_in_flight=true,credential_refresh_started_at=now()`,
 `update sellerpilot_private.smartstore_create_category_attribute_sources set expires_at=now()+interval '1 hour'`,
 `update sellerpilot_private.smartstore_create_category_attribute_sources set assignment_revision=4`,
 `update sellerpilot_private.channel_operation_attempts set owner_id=gen_random_uuid()`,
 `insert into sellerpilot_private.smartstore_create_final_transports values('${ids.j}')`,
 `insert into sellerpilot_private.smartstore_create_final_completions values('${ids.j}')`
 ]){await db.exec('begin');await db.exec(patch);const sql=fixtureMigration(await rows(db)).replace(/^begin;$/m,'').replace(/^commit;$/m,'');await assert.rejects(db.exec(sql),/SMARTSTORE_UNCLAIMED_EXPIRY_EVIDENCE_MISMATCH/);await db.exec('rollback');}
 }finally{await db.close();}
});
test('production preimage hashes fail closed against a different row snapshot',async()=>{const db=await setup();try{await assert.rejects(db.exec(migration),/SMARTSTORE_UNCLAIMED_EXPIRY_PREIMAGE_DRIFT/);await db.exec('rollback');assert.equal((await rows(db)).j.row.status,'queued');}finally{await db.close();}});
